import { Global, Inject, Logger, Module, type OnModuleDestroy } from '@nestjs/common';
import { resolve } from 'node:path';
import { drizzle, type NodePgDatabase } from 'drizzle-orm/node-postgres';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import { Pool } from 'pg';
import { ENV, type Env } from '../config/env';
import * as schema from './schema';

export type Db = NodePgDatabase<typeof schema>;

/** DI tokens. Inject the Drizzle client with `@Inject(DB) db: Db`. */
export const DB = Symbol('DB');
const PG_POOL = Symbol('PG_POOL');

// Generated by `bun run db:generate`; resolved from dist/db/ → apps/api/drizzle.
const MIGRATIONS_DIR = resolve(__dirname, '../../drizzle');

@Global()
@Module({
  providers: [
    {
      provide: PG_POOL,
      inject: [ENV],
      useFactory: (env: Env) => new Pool({ connectionString: env.DATABASE_URL }),
    },
    {
      provide: DB,
      inject: [PG_POOL],
      // Async factory: Nest waits for it, so migrations finish before the app
      // serves requests or the runner claims jobs. One command, no manual step.
      useFactory: async (pool: Pool): Promise<Db> => {
        const db = drizzle(pool, { schema });
        await migrate(db, { migrationsFolder: MIGRATIONS_DIR });
        new Logger('DbModule').log('Migrations applied');
        return db;
      },
    },
  ],
  exports: [DB],
})
export class DbModule implements OnModuleDestroy {
  constructor(@Inject(PG_POOL) private readonly pool: Pool) {}

  async onModuleDestroy(): Promise<void> {
    await this.pool.end();
  }
}
